<x-filament-widgets::widget>
    <div class="space-y-5" x-data="titanGoDashboard({locationEndpoint:@js($locationEndpoint),missionPackEndpoint:@js($missionPackEndpoint),helpEndpoint:@js($helpEndpoint),unsafeSiteEndpoint:@js($unsafeSiteEndpoint),liveStatusEndpoint:@js($liveStatusEndpoint),syncEndpoint:@js($syncEndpoint),copilotEndpoint:@js($copilotEndpoint)})" x-init="boot()">
        <section class="overflow-hidden rounded-3xl bg-gradient-to-br from-orange-600 via-orange-500 to-amber-400 p-5 text-white shadow-sm sm:p-6"><div class="flex flex-col gap-5 lg:flex-row lg:items-center lg:justify-between"><div><p class="text-sm font-semibold uppercase tracking-wide text-orange-100">Today</p><h2 class="mt-1 text-3xl font-black tracking-tight">Field dashboard</h2><p class="mt-2 max-w-2xl text-sm text-orange-50">Next job, proof photos, safety, offline pack, and location sharing in one workspace.</p></div><div class="grid grid-cols-2 gap-2 sm:grid-cols-4 lg:min-w-[420px]"><div class="rounded-2xl bg-white/15 p-3"><div class="text-xs text-orange-100">Today</div><div class="text-2xl font-bold">{{ $stats['today'] }}</div></div><div class="rounded-2xl bg-white/15 p-3"><div class="text-xs text-orange-100">Open</div><div class="text-2xl font-bold">{{ $stats['open'] }}</div></div><div class="rounded-2xl bg-white/15 p-3"><div class="text-xs text-orange-100">Next 2h</div><div class="text-2xl font-bold">{{ $stats['due_next'] }}</div></div><div class="rounded-2xl bg-white/15 p-3"><div class="text-xs text-orange-100">Late</div><div class="text-2xl font-bold">{{ $stats['late'] }}</div></div></div></div></section>
        <section class="grid gap-4 xl:grid-cols-[1.2fr_.8fr]"><div class="rounded-3xl border border-gray-200 bg-white p-5 shadow-sm dark:border-gray-800 dark:bg-gray-900">@php($nextJob=$jobs->first())<p class="text-sm font-semibold text-primary-600">Next up</p><h3 class="mt-1 text-2xl font-bold text-gray-950 dark:text-white">{{ $nextJob?->reference ?? 'No assigned job right now' }}</h3><p class="mt-1 text-sm text-gray-500">{{ $nextJob?->description ?: 'Assigned work will appear here with check-in, checklist, photo, and safety actions.' }}</p><div class="mt-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><a href="{{ url('/titango/check-in') }}" class="rounded-2xl bg-gray-950 p-4 text-white shadow-sm dark:bg-white dark:text-gray-950"><div class="font-bold">Check in</div><div class="text-xs opacity-75">Arrival + GPS proof</div></a><a href="{{ url('/titango/checklist') }}" class="rounded-2xl border border-gray-200 p-4 dark:border-gray-800"><div class="font-bold">Checklist</div><div class="text-xs text-gray-500">Room tasks</div></a><a href="{{ url('/titango/proof') }}" class="rounded-2xl border border-gray-200 p-4 dark:border-gray-800"><div class="font-bold">Photos</div><div class="text-xs text-gray-500">Before / after / issue</div></a><a href="{{ url('/titango/safety') }}" class="rounded-2xl border border-red-200 bg-red-50 p-4 dark:border-red-900 dark:bg-red-950/30"><div class="font-bold text-red-800 dark:text-red-200">Safety</div><div class="text-xs text-red-700 dark:text-red-300">Help or unsafe site</div></a></div></div><div class="rounded-3xl border border-gray-200 bg-white p-5 shadow-sm dark:border-gray-800 dark:bg-gray-900"><p class="text-sm font-semibold text-primary-600">Live tools</p><div class="mt-4 space-y-3"><button type="button" @click="toggleLocation" class="flex w-full items-center justify-between rounded-2xl border border-gray-200 p-4 text-left dark:border-gray-800"><span><span class="block font-bold" x-text="locationOn?'Location sharing on':'Turn on location'"></span><span class="text-xs text-gray-500">Arrival proof and safety.</span></span><span class="rounded-full px-3 py-1 text-xs font-semibold" :class="locationOn?'bg-green-100 text-green-700':'bg-gray-100 text-gray-600'" x-text="locationOn?'On':'Off'"></span></button><button type="button" @click="downloadMissionPack" class="flex w-full items-center justify-between rounded-2xl border border-gray-200 p-4 text-left dark:border-gray-800"><span><span class="block font-bold">Offline pack</span><span class="text-xs text-gray-500" x-text="missionStatus"></span></span><span class="text-xs font-semibold text-primary-600">Download</span></button><button type="button" @click="askNext" class="flex w-full items-center justify-between rounded-2xl border border-gray-200 p-4 text-left dark:border-gray-800"><span><span class="block font-bold">Co-Pilot</span><span class="text-xs text-gray-500" x-text="copilotStatus"></span></span><span class="text-xs font-semibold text-primary-600">Ask</span></button></div></div></section>
    </div><script>function titanGoDashboard(c){return{...c,locationOn:localStorage.getItem('titango.location.enabled')==='1',missionStatus:'Save jobs, checklist and route for offline use.',copilotStatus:'Ask what to do next.',boot(){this.syncLiveStatus('available')},csrf(){return document.querySelector('meta[name="csrf-token"]')?.content||''},async post(url,payload={}){return fetch(url,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','Accept':'application/json','X-Requested-With':'XMLHttpRequest','X-CSRF-TOKEN':this.csrf()},body:JSON.stringify(payload)})},toggleLocation(){if(!navigator.geolocation){this.copilotStatus='Location is not available.';return}if(this.locationOn){this.locationOn=false;localStorage.setItem('titango.location.enabled','0');this.syncLiveStatus('location_off');return}navigator.geolocation.getCurrentPosition(async(p)=>{this.locationOn=true;localStorage.setItem('titango.location.enabled','1');await this.post(this.locationEndpoint,{enabled:true,latitude:p.coords.latitude,longitude:p.coords.longitude,accuracy:p.coords.accuracy,recorded_at:new Date().toISOString()});this.syncLiveStatus('location_on')},()=>{this.copilotStatus='Location permission blocked.'},{enableHighAccuracy:true,timeout:10000})},async downloadMissionPack(){this.missionStatus='Downloading...';try{const r=await fetch(this.missionPackEndpoint,{headers:{'Accept':'application/json'}});localStorage.setItem('titango.missionPack',JSON.stringify(await r.json()));this.missionStatus='Offline pack saved.'}catch(e){this.missionStatus='Offline pack queued.'}},async askNext(){this.copilotStatus='Thinking...';try{const r=await this.post(this.copilotEndpoint,{command:'What should I do next?',context:{screen:'dashboard',location_enabled:this.locationOn,online:navigator.onLine}});const d=await r.json();this.copilotStatus=d.reply||d.message||'Next action ready.'}catch(e){this.copilotStatus='Co-Pilot unavailable offline.'}},async syncLiveStatus(s){try{await this.post(this.liveStatusEndpoint,{status:s,online:navigator.onLine})}catch(e){}}}}</script>
</x-filament-widgets::widget>
